# A ship gate for an AI-assisted change: every check must pass
change = {
    "files": ["billing/charge.py", "billing/test_charge.py", "notes.txt"],
    "added_lines": ["retry(call)", "key = 'AKIA_PLACEHOLDER'", "x = 1"],
    "tests_pass": True,
    "has_failure_path_test": False,
    "reviewed_by_human_who_understands": True,
}
RISKY = ("billing/", "auth/", "migrations/")   # money, access, data

def gate(ch):
    problems = []
    if not ch["tests_pass"]:
        problems.append("tests fail")
    if any("AKIA" in ln or "password" in ln for ln in ch["added_lines"]):
        problems.append("possible secret in diff")
    if not ch["has_failure_path_test"]:
        problems.append("no failure-path test")
    risky = [f for f in ch["files"] if f.startswith(RISKY)]
    if risky and not ch["reviewed_by_human_who_understands"]:
        problems.append("risky area needs an expert reviewer")
    if any(f.endswith(".txt") for f in ch["files"]):
        problems.append("unexpected file: review why")
    return problems

print("files:", change["files"])
issues = gate(change)
for p in issues:
    print("BLOCK:", p)
print("verdict:", "ship with staged rollout" if not issues else "do not ship yet")
